/** 兜底徽章底色板（按包名稳定哈希选取，不用随机）。 */
const FALLBACK_COLORS = ['#FF5A36', '#1F88C0', '#5FA04E', '#88171A', '#6B5BD2', '#0E9AA7']

function hashOf(s: string): number {
  let h = 0
  for (let i = 0; i < s.length; i++) h = (h * 31 + s.charCodeAt(i)) >>> 0
  return h
}

const logo = computed(() => LOGOS[props.name])

/** 兜底徽章文字：1-2 个首字母（Node.js → "N"，HAProxy → "HA"）。 */
const initials = computed(() => {
  const s = (props.label ?? props.name).replace(/[^A-Za-z0-9]/g, ' ')
  const words = s.split(/\s+/).filter(Boolean)
  if (!words.length) return props.name.slice(0, 2).toUpperCase()
  if (words.length === 1) return words[0].slice(0, 2).toUpperCase()
  return (words[0][0] + words[1][0]).toUpperCase()
})
const fallbackColor = computed(() => FALLBACK_COLORS[hashOf(props.name) % FALLBACK_COLORS.length])
</script>

<template>
  <!-- B：有官方 logo。单 path 单色，直接填品牌色（不用 mask，也就不会吃 stroke） -->
  <svg v-if="logo" class="pkg-icon" :width="size" :height="size" viewBox="0 0 24 24"
       role="img" :aria-label="`${logo.brand} 官方标识`">
    <path :d="logo.d" :fill="logo.color" />
  </svg>
  <!-- A 兜底：首字母徽章 -->
  <span v-else class="pkg-icon pkg-icon-fb" :style="{
    width: size + 'px', height: size + 'px',
    background: fallbackColor, fontSize: Math.round(size * 0.42) + 'px',
  }" :title="`${label ?? name}（暂无官方图标）`">{{ initials }}</span>
</template>

<style scoped>
.pkg-icon { display: block; flex: none; }
/* 首字母徽章：圆角方块 + 白字。font-size 由 JS 按 size 算，容器宽高由 JS 内联，
   故此处只管形状与排版。 */
.pkg-icon-fb {
  display: inline-flex; align-items: center; justify-content: center;
  border-radius: 5px; color: #fff; font-weight: 700; letter-spacing: -.5px;
  line-height: 1;
}
</style>
